206		raw := &IdentityProvider{
207			ID:               identityProvider.Id,
208			UID:              identityProvider.Uid,
209			Name:             identityProvider.Name,
210			Type:             identityProvider.Type,
211			IdentifierFilter: identityProvider.IdentifierFilter,
212		}
213		configRaw, err := convertIdentityProviderConfigToRaw(identityProvider.Type, identityProvider.Config)
