221	func convertIdentityProviderConfigFromRaw(identityProviderType storepb.IdentityProvider_Type, raw string) (*storepb.IdentityProviderConfig, error) {
222		config := &storepb.IdentityProviderConfig{}
223		if identityProviderType == storepb.IdentityProvider_OAUTH2 {
224			oauth2Config := &storepb.OAuth2Config{}
225			if err := protojsonUnmarshaler.Unmarshal([]byte(raw), oauth2Config); err != nil {
226				return nil, errors.Wrap(err, "Failed to unmarshal OAuth2Config")
227			}
228			config.Config = &storepb.IdentityProviderConfig_Oauth2Config{Oauth2Config: oauth2Config}
229		}
230		return config, nil
231	}
232	
233	func convertIdentityProviderConfigToRaw(identityProviderType storepb.IdentityProvider_Type, config *storepb.IdentityProviderConfig) (string, error) {
234		raw := ""
235		if identityProviderType == storepb.IdentityProvider_OAUTH2 {
236			bytes, err := protojson.Marshal(config.GetOauth2Config())
237			if err != nil {
238				return "", errors.Wrap(err, "Failed to marshal OAuth2Config")
239			}
240			raw = string(bytes)
241		}
242		return raw, nil
243	}
