17	func (s *APIV1Service) CreateIdentityProvider(ctx context.Context, request *v1pb.CreateIdentityProviderRequest) (*v1pb.IdentityProvider, error) {
18		currentUser, err := s.fetchCurrentUser(ctx)
19		if err != nil {
20			return nil, status.Errorf(codes.Internal, "failed to get user: %v", err)
21		}
22		if currentUser == nil {
23			return nil, status.Errorf(codes.Unauthenticated, "user not authenticated")
24		}
25		if currentUser.Role != store.RoleAdmin {
26			return nil, status.Errorf(codes.PermissionDenied, "permission denied")
27		}
28	
29		idpUID, err := ValidateAndGenerateUID(request.IdentityProviderId)
30		if err != nil {
31			return nil, err
32		}
33		if s.Store.IsIdentityProviderDeploymentConfigured(idpUID) {
34			return nil, status.Errorf(codes.FailedPrecondition, "identity provider %q is configured by the deployment", idpUID)
35		}
36	
37		storeIdp := convertIdentityProviderToStore(request.IdentityProvider)
38		storeIdp.Uid = idpUID
39	
40		identityProvider, err := s.Store.CreateIdentityProvider(ctx, storeIdp)
41		if err != nil {
42			return nil, status.Errorf(codes.Internal, "failed to create identity provider, error: %+v", err)
43		}
44		return convertIdentityProviderFromStore(identityProvider), nil
45	}
