47	func (s *APIV1Service) ListIdentityProviders(ctx context.Context, _ *v1pb.ListIdentityProvidersRequest) (*v1pb.ListIdentityProvidersResponse, error) {
48		identityProviders, err := s.Store.ListIdentityProviders(ctx, &store.FindIdentityProvider{})
49		if err != nil {
50			return nil, status.Errorf(codes.Internal, "failed to list identity providers, error: %+v", err)
51		}
52	
53		response := &v1pb.ListIdentityProvidersResponse{
54			IdentityProviders: []*v1pb.IdentityProvider{},
55		}
56		for _, identityProvider := range identityProviders {
57			response.IdentityProviders = append(response.IdentityProviders, convertIdentityProviderFromStore(identityProvider))
58		}
